   149	
   150						jpql.append("e.")
   151								.append(field)
   152								.append(" = :")
   153								.append(parameterName);
   154	
   155						index++;
   156					}
   157				}
   158	
   159				TypedQuery<T> query = entityManager.createQuery(jpql.toString(), entityClass);
   160	
   161				if (searchFields != null && !searchFields.isEmpty()) {
   162					for (Map.Entry<String, Object> entry : searchFields.entrySet()) {
