public Long registerNewReport(
        Long userId,
        Map<String, Object> reportData
) {

    if (userId == null) {
        System.err.println("[ReportService] Creation cancelled: user ID is null.");
        return null;
    }
    if (reportData == null) {
        System.err.println("[ReportService] Creation cancelled: report data is null.");
        return null;
    }
    try {
        User user = persistenceService.findById(
                User.class,
                userId
        );

        if (!(user instanceof Citizen)) {
            System.err.println("[ReportService] User not found or not a citizen. User ID = " + userId);
            return null;
        }
        Citizen citizen = (Citizen) user;

        String title = extractString(reportData.get("title"));
        String description = extractString(reportData.get("description"));
        ReportCategory category = null;

        if (reportData.get("category") instanceof ReportCategory) {
            category = (ReportCategory) reportData.get("category");
        }

        String city = extractString(reportData.get("city"));
        String cap = extractString(reportData.get("cap"));
        String street = extractString(reportData.get("street"));
        String streetNumber = extractString(reportData.get("streetNumber"));
        String municipalArea = extractString(reportData.get("municipalArea"));

        // Implementation note for the English standalone variant.
        if (isBlank(title)
                || isBlank(description)
                || category == null
                || isBlank(city)
                || isBlank(cap)
                || isBlank(street)
                || isBlank(streetNumber)
                || isBlank(municipalArea)) {

            System.err.println("[ReportService] Invalid required data.");
            return null;
        }

        Report report = new Report(
                title,
                description,
                category,
                city,
                cap,
                street,
                streetNumber,
                municipalArea,
                citizen
        );

        // Implementation note for the English standalone variant.

        // Implementation note for the English standalone variant.
        Date reportDate = null;
        if (reportData.get("reportDate") instanceof Date) {
            reportDate = (Date) reportData.get("reportDate");
        }

        if (reportDate != null) {
            report.setDateReport(reportDate);
        }

        // Handles the optional attached image.
        String imageAttached = extractString(reportData.get("imageAttached"));
        if (!isBlank(imageAttached)) {
            report.setImageAttached(imageAttached);
        }

        // Persist the completed report.
        persistenceService.save(report);

        if (report.getReportId() == null) {
            System.err.println("[ReportService] Report saved but its ID was not populated.");
            return null;
        }
        return report.getReportId();

    } catch (RuntimeException e) {
        System.err.println("[ReportService] Error while creating the report.");
        e.printStackTrace();
        return null;
    }
