    }
    Map<String, Object> searchFields = new HashMap<>();
    if (criteriaFilter != null) {
        searchFields.putAll(criteriaFilter);
    }
    List<Report> reports = persistenceService.findByFields(
            Report.class,
            searchFields
    );
    return mapListReports(reports);
}
