) {
    if (userId == null || reportId == null) {
        return null;
    }
    Report report = persistenceService.findById(
            Report.class,
            reportId
    );
    if (report == null) {
        return null;
    }
    Map<String, Object> details = mapReport(report);
    Map<String, Object> searchFieldsNotifications = new HashMap<>();
    searchFieldsNotifications.put("report.reportId", reportId);
    List<Notification> notifications = persistenceService.findByFields(
            Notification.class,
            searchFieldsNotifications
    );
    details.put("notifications", mapNotificationsReport(notifications));
    /**
     * Documents this component's behavior and responsibilities.
     */
    Map<String, Object> searchFieldsNote = new HashMap<>();
    searchFieldsNote.put("report.reportId", reportId);
    List<InternalNote> note = persistenceService.findByFields(
            InternalNote.class,
            searchFieldsNote
    );
    details.put("internalNotes", mapInternalNotesReport(note));
    return details;
}
